#include <stdio.h>
#define MAX_NUMBER 100

void points(int *votes, int **students, int num);
void count(int **students, int *ranks, int num);

int main(void)
{
    int num, votes[MAX_NUMBER * (MAX_NUMBER + 1)];
    int *students[MAX_NUMBER] = {0};
    int ranks[MAX_NUMBER];
    int offset = 0;

    if (scanf("%d", &num) != 1) return 1;
    for (int i = 0; i < num; ++i) {
        int m;
        if (scanf("%d", &m) != 1) return 1;
        votes[offset++] = m;
        for (int j = 0; j < m; ++j) {
            if (scanf("%d", &votes[offset++]) != 1) return 1;
        }
    }

    for (int i = 0; i < num; ++i) ranks[i] = -1;
    points(votes, students, num);
    offset = 0;
    for (int i = 0; i < num; ++i) {
        if (students[i] != votes + offset) {
            fprintf(stderr, "points did not point to the record for student %d\n", i);
            return 1;
        }
        printf("%d\n", students[i][0]);
        offset += 1 + students[i][0];
    }
    count(students, ranks, num);
    for (int i = 0; i < num; ++i) printf("%d\n", ranks[i]);
    return 0;
}

