#include <stdio.h>

int main(void)
{
    int n, quantity[99], total = 0;
    if (scanf("%d", &n) != 1) return 1;
    for (int i = 0; i < n; ++i) scanf("%d", &quantity[i]);
    for (int i = 0; i < n; ++i) {
        int price;
        scanf("%d", &price);
        total += quantity[i] * price;
    }
    printf("%d\n", total);
    return 0;
}

#include <stdio.h>
int main(void) {
    int n,a[100][100];
    scanf("%d",&n);
    for(int i=0;i<n;i++)for(int j=0;j<n;j++)scanf("%d",&a[i][j]);
    for(int i=0;i<n;i+=2){
        for(int j=0;j<n;j+=2){
            int best=a[i][j];
            for(int r=0;r<2;r++)for(int c=0;c<2;c++)
                if(a[i+r][j+c]>best)best=a[i+r][j+c];
            printf("%s%d",j?" ":"",best);
        }
        puts("");
    }
    return 0;
}
